  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inventory_batch` (`batch_no`),
  KEY `idx_inventory_product` (`product_id`),
  KEY `idx_inventory_supplier` (`supplier_id`),
  KEY `idx_inventory_status` (`status`),
  KEY `idx_inventory_expiry` (`expiration_date`),
  CONSTRAINT `fk_inventory_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_inventory_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


